import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"TuneWeave","description":"统一、可扩展的跨平台音乐 API","frontmatter":{"title":"TuneWeave","description":"统一、可扩展的跨平台音乐 API","outline":"deep"},"headers":[],"relativePath":"projects/tuneweave/index.md","filePath":"projects/tuneweave/index.md"}'),t={name:"projects/tuneweave/index.md"};function l(p,e,o,r,d,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="tuneweave" tabindex="-1">TuneWeave <a class="header-anchor" href="#tuneweave" aria-label="Permalink to &quot;TuneWeave&quot;">​</a></h1><p>统一、可扩展的跨平台音乐 API，为不同音乐平台提供一致的访问接口。</p><p>TuneWeave 使用 Rust 构建，目标是在保持较小存储体积、较低运行占用和快速启动的同时，把不同音乐平台的检索、歌单、媒体解析和账户能力统一为稳定的 HTTP API。</p><p>统一资源引用、请求参数和响应模型目前连接网易云音乐、QQ 音乐、B 站、酷狗、咪咕、酷我与汽水音乐，并支持多账户、Uni Playlist 和播放失败后的跨平台资源回退。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>下载适合当前系统的预编译包并运行：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">./tuneweave</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Windows 使用：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tuneweave.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也可以从源码启动：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cargo run --release -p tuneweave-server --bin tuneweave</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>服务默认监听 <code>127.0.0.1:7832</code>。确认服务可用：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/healthz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/v1/platforms</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/v1/capabilities</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="开发者文档" tabindex="-1">开发者文档 <a class="header-anchor" href="#开发者文档" aria-label="Permalink to &quot;开发者文档&quot;">​</a></h2><ul><li><a href="./docs/getting-started.html">安装与配置</a></li><li><a href="./docs/api-v1.html">HTTP API v1</a></li><li><a href="./docs/authentication.html">登录与调用方托管凭证</a></li><li><a href="./docs/uni-playlist.html">Uni Playlist</a></li><li><a href="docs/routes.json">完整路由目录</a></li><li><a href="release-manifest.json">版本下载清单</a></li></ul><p>所有业务响应使用统一 JSON 包络。资源引用带有平台前缀，例如 <code>netease:123456</code>、<code>qq:0039MnYb0qxYhV</code> 和 <code>bilibili:bvid:BV1xx411c7mD</code>。调用方可通过 <code>platform</code> 选择内容或账户平台，通过 <code>account</code> 选择服务器托管账户，也可使用 <code>X-TuneWeave-Credential</code> 携带由调用方保存的登录凭证。</p><p>接口可用性应以运行实例返回的 <code>/v1/capabilities</code> 为准。媒体端点返回平台提供的 URL 和必要请求头；TuneWeave 不代理媒体内容。</p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>TuneWeave 采用 <a href="./LICENSE.html">MIT OR Apache-2.0</a> 双许可证。第三方研究来源见 <a href="./THIRD_PARTY_NOTICES.html">THIRD_PARTY_NOTICES.md</a>。</p>`,19)])])}const b=a(t,[["render",l]]);export{u as __pageData,b as default};
